<script setup lang="ts">
import {ref,computed,watch} from 'vue';
import {ElMessage} from 'element-plus';
import {api,message} from '../api';
import {label,date} from '../fulfillment';
import {useAuth} from '../stores/auth';
import ContractSeal from './ContractSeal.vue';
import ContractTemplatePreview from './ContractTemplatePreview.vue';
const props=defineProps<{modelValue:boolean;contract:any;readOnly?:boolean;revisionNumber?:number}>();const emit=defineEmits(['update:modelValue','signed']);const auth=useAuth();
const docType=ref('MAIN'),placed=ref(false),ack=ref(false),busy=ref(false),error=ref(''),position=ref({x:30,y:84}),paper=ref<HTMLElement>(),preview=ref(false);
const revision=computed(()=>props.contract?.revisions.find((r:any)=>r.number===props.revisionNumber)||props.contract?.revisions.at(-1));
const doc=computed(()=>revision.value?.documents.find((d:any)=>d.type===docType.value));
const role=computed(()=>auth.user?.businessEntityId===props.contract?.traderId?'TRADER':auth.user?.businessEntityId===props.contract?.carrierId?'CARRIER':'PLATFORM');
const sealName=computed(()=>props.contract?.snapshot[role.value.toLowerCase()]?.name||auth.user?.businessEntity.name||'');
const signingReady=computed(()=>props.contract?.signing?.enabled===true&&!!props.contract?.signing?.sealUrl);
const signatures=computed(()=>revision.value?.signatures.filter((s:any)=>s.documentType===docType.value)||[]);
const ownSigned=computed(()=>signatures.value.some((s:any)=>s.role===role.value));
const canSign=computed(()=>!props.readOnly&&auth.can('contract:write')&&revision.value?.status==='SIGNING'&&revision.value?.id===props.contract?.revisions.at(-1).id&&!ownSigned.value&&(role.value!=='PLATFORM'||docType.value==='ADDENDUM'&&revision.value.mode==='B'));
function reset(){placed.value=false;ack.value=false;error.value='';position.value={x:role.value==='TRADER'?30:role.value==='CARRIER'?70:50,y:84};}
watch(()=>props.modelValue,v=>{if(v){docType.value=revision.value?.documents.find((d:any)=>!revision.value.signatures.some((s:any)=>s.role===role.value&&s.documentType===d.type)&&(role.value!=='PLATFORM'||d.type==='ADDENDUM'))?.type||'MAIN';reset();}});
watch(docType,reset);
function placement(s:any){try{const p=JSON.parse(s.placement||'{}');return {x:p.x??(s.role==='TRADER'?30:s.role==='CARRIER'?70:50),y:p.y??84};}catch{return {x:50,y:84};}}
function move(event:MouseEvent){if(!placed.value||!canSign.value||!paper.value||(event.target as HTMLElement).closest('button'))return;const r=paper.value.getBoundingClientRect();position.value={x:Math.max(12,Math.min(88,(event.clientX-r.left)/r.width*100)),y:Math.max(12,Math.min(88,(event.clientY-r.top)/r.height*100))};}
function nudge(event:KeyboardEvent){const delta:Record<string,number[]>={ArrowLeft:[-1,0],ArrowRight:[1,0],ArrowUp:[0,-1],ArrowDown:[0,1]};if(delta[event.key]){event.preventDefault();position.value={x:Math.max(12,Math.min(88,position.value.x+delta[event.key][0])),y:Math.max(12,Math.min(88,position.value.y+delta[event.key][1]))};}}
async function sign(){if(!signingReady.value){error.value='企业签章尚未配置，请联系平台管理员接入签署服务';return;}busy.value=true;error.value='';try{await api.post(`/contracts/${props.contract.id}/sign`,{version:props.contract.version,documentType:docType.value,acknowledged:ack.value,seal:position.value});placed.value=false;ack.value=false;emit('signed');ElMessage.success('签章与签署记录已保存');}catch(e){error.value=message(e);}finally{busy.value=false;}}
function jump(selector:string){paper.value?.querySelector(selector)?.scrollIntoView({behavior:'smooth',block:'start'});}
</script>
<template><el-dialog :model-value="modelValue" @update:model-value="emit('update:modelValue',$event)" :title="(readOnly?'合同文件 · ':'合同签署 · ')+contract?.businessNo" width="94vw" top="4vh" class="contract-signing-dialog" destroy-on-close><div class="signing-toolbar"><el-radio-group v-model="docType"><el-radio-button v-for="d in revision?.documents" :key="d.type" :value="d.type">{{label(d.type)}}</el-radio-button></el-radio-group><span>第 {{revision?.number}} 版 · {{label(revision?.status)}}</span><el-button v-if="doc?.fileId" link type="primary" @click="preview=true">预览模板附件</el-button></div><el-alert v-if="error" :title="error" type="error" :closable="false"/><div class="signing-layout"><aside class="signing-catalog"><h3>合同目录</h3><el-button link @click="jump('.document-title')">合同及签约主体</el-button><el-button link @click="jump('.document-content')">运输与结算条款</el-button><el-button link @click="jump('.document-parties')">签章及签署记录</el-button><div class="catalog-note">{{contract?.snapshot.origin}}<br/>↓<br/>{{contract?.snapshot.destination}}</div></aside><div class="signing-scroll"><article ref="paper" class="signing-paper" :class="{'is-placing':placed&&canSign}" @click="move"><h1 class="document-title">{{doc?.name}}</h1><div class="document-code">合同编号：{{contract?.businessNo}}</div><div class="document-identity"><p>甲方（贸易方）：<strong>{{contract?.snapshot.trader.name}}</strong></p><p>乙方（承运方）：<strong>{{contract?.snapshot.carrier.name}}</strong></p></div><pre class="document-content">{{doc?.body}}</pre><div class="document-parties"><div v-for="party in (docType==='ADDENDUM'&&revision?.mode==='B'?['TRADER','CARRIER','PLATFORM']:['TRADER','CARRIER'])" :key="party"><strong>{{label(party)}}签章</strong><p>{{contract?.snapshot[party.toLowerCase()]?.name}}</p><small>{{signatures.find((s:any)=>s.role===party&&s.sealUrl)?'已签署':signatures.some((s:any)=>s.role===party)?'签署记录待核验':'待签署'}}</small></div></div><div v-for="s in signatures" :key="s.id" class="placed-seal saved-seal" :style="{left:placement(s).x+'%',top:placement(s).y+'%'}"><ContractSeal :name="s.sealName||contract?.snapshot[s.role.toLowerCase()]?.name||label(s.role)" :image-url="s.sealUrl"/></div><button v-if="placed&&canSign" class="placed-seal draft-seal" :style="{left:position.x+'%',top:position.y+'%'}" aria-label="调整印章位置，可用方向键移动" @keydown="nudge"><ContractSeal :name="sealName" :image-url="contract?.signing?.sealUrl"/></button><p class="document-digest">正文校验 SHA-256：{{revision?.digest}}</p></article></div><aside class="signing-tools"><h3>{{canSign?'本企业电子印章':'签署记录'}}</h3><template v-if="canSign"><div class="seal-preview"><ContractSeal :name="sealName" :image-url="contract?.signing?.sealUrl"/></div><strong>{{sealName}}</strong><p class="muted">{{signingReady?'本企业授权签章':'待配置企业签章'}}</p><div class="seal-actions"><el-button @click="placed=false">清除印章</el-button><el-button type="primary" :disabled="!signingReady" @click="placed=true">插入印章</el-button></div><p class="seal-help">插入后可点击正文调整位置，或聚焦印章用方向键微调。</p><el-checkbox v-model="ack" class="sign-ack">我已阅读本版本合同及附件，确认代表本企业签署本版本合同</el-checkbox><p v-if="!signingReady" class="seal-help">企业签章尚未配置，请联系平台管理员接入签署服务。</p></template><div v-for="s in signatures" :key="s.id" class="sign-record"><el-tag :type="s.sealUrl?'success':'info'">{{label(s.role)}} · {{s.sealUrl?'已签署':'记录待核验'}}</el-tag><strong>{{s.signerName}}</strong><span>{{date(s.signedAt)}}</span></div><el-empty v-if="!canSign&&!signatures.length" description="本文件暂无签署记录" :image-size="55"/></aside></div><template #footer><el-button @click="emit('update:modelValue',false)">{{readOnly?'关闭':'稍后签署'}}</el-button><el-button v-if="canSign" type="primary" :disabled="!signingReady||!placed||!ack" :loading="busy" @click="sign">确认签署</el-button><span v-if="!canSign&&ownSigned" class="signed-note">{{signatures.some((s:any)=>s.role===role&&s.sealUrl)?'本企业已签署此文件':'本企业签署记录待核验'}}</span></template></el-dialog><ContractTemplatePreview v-model="preview" :template="{name:doc?.name,body:doc?.body,file:doc?.file}" :source="doc?.fileId?`/contracts/${contract?.id}/templates/${doc.fileId}`:undefined"/></template>
<style scoped>.signing-toolbar{display:flex;gap:20px;align-items:center;margin-bottom:16px}.signing-toolbar>span{font-size:12px;color:#89919c}.signing-layout{display:grid;grid-template-columns:175px minmax(0,1fr) 260px;border:1px solid #e4e8ee;height:68vh;background:#f3f5f8;border-radius:8px;overflow:hidden}.signing-catalog,.signing-tools{background:#fff;padding:22px 18px;overflow:auto}.signing-catalog{border-right:1px solid #e4e8ee}.signing-layout h3{font-size:14px;margin-bottom:20px}.signing-catalog .el-button{display:flex;margin:0 0 20px;font-size:12px}.catalog-note{margin-top:36px;line-height:2;color:#89919c;font-size:12px}.signing-scroll{padding:24px;overflow:auto}.signing-paper{position:relative;background:#fff;padding:44px 40px 36px;min-height:950px;max-width:820px;margin:auto;box-shadow:0 2px 8px #1d283312}.document-title{text-align:center;font-size:26px;line-height:1.6;margin:32px 0}.document-code{font-size:12px;margin-bottom:25px;color:#747d89}.document-identity{font-size:14px;line-height:2.3;margin-bottom:26px}.document-content{font:13px/2.15 var(--el-font-family);white-space:pre-wrap;overflow-wrap:anywhere}.document-parties{display:flex;gap:24px;min-height:180px;margin-top:35px;padding-top:24px;border-top:1px solid #eee;font-size:12px}.document-parties>div{flex:1}.document-parties p{margin-top:12px}.document-parties small{display:block;margin-top:16px;color:#a0a7af}.document-digest{overflow-wrap:anywhere;font-size:10px;color:#a0a7af;margin-top:30px}.placed-seal{position:absolute;width:130px;height:130px;transform:translate(-50%,-50%);z-index:1}.draft-seal{background:transparent;border:1px dashed #d34d54;cursor:move;padding:0}.draft-seal:focus-visible{outline:2px solid #ed252e}.saved-seal{opacity:.85;pointer-events:none}.is-placing{cursor:crosshair}.signing-tools{border-left:1px solid #e4e8ee;font-size:12px}.seal-preview{width:150px;height:150px;border:1px solid #eee;padding:5px;margin:0 auto 20px}.signing-tools>strong{display:block;text-align:center;line-height:1.7}.signing-tools>.muted{text-align:center;margin:6px 0 20px}.seal-actions{display:flex;justify-content:center}.seal-help{font-size:12px;color:#8791a0;line-height:1.9;margin:18px 0}.sign-ack{white-space:normal;height:auto;align-items:flex-start}.sign-ack :deep(.el-checkbox__label){white-space:normal;font-size:12px;line-height:1.8}.sign-record{display:flex;flex-direction:column;gap:12px;padding:14px 0;border-bottom:1px solid #eee}.sign-record span{color:#89919c;font-size:11px}.signed-note{margin-left:15px;color:#52805c;font-size:12px}@media(max-width:1100px){.signing-layout{grid-template-columns:minmax(0,1fr) 220px}.signing-catalog{display:none}.signing-scroll{padding:15px}.signing-paper{padding:24px}.placed-seal{width:110px;height:110px}}@media(max-width:650px){.signing-layout{display:block;height:65vh;overflow:auto}.signing-scroll{overflow:visible}.signing-tools{border-left:0;border-top:1px solid #ddd}.signing-toolbar{flex-wrap:wrap}.signing-paper{min-height:900px}.document-title{font-size:20px}}</style>
